function toggleExportMenu(force) {
    var drop = document.getElementById('exportMenuDrop');
    if (!drop) return;
    var show = (force === true) || (drop.style.display === 'none' || !drop.style.display);
    drop.style.display = show ? 'block' : 'none';
}
function runExportForm(form) {
    toggleExportMenu(false);
    if (form === 'calendar') {
        if (typeof exportCalendarToExcel === 'function') exportCalendarToExcel();
    } else if (form === 'debtors') {
        exportDebtorsToExcel();
    }
}
function exportDebtorsToExcel() {
    var d = new Date();
    var iso = d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
    var params = new URLSearchParams();
    params.set('date', iso);
    var deptFilter = document.getElementById('calDeptFilter');
    if (deptFilter && deptFilter.value) params.set('department', deptFilter.value);
    var teamFilter = document.getElementById('calTeamFilter');
    if (teamFilter && teamFilter.value) params.set('team', teamFilter.value);
    if (typeof notify === 'function') notify('Считаем, кто не заполнил отчёт...', 'info');
    window.open('/api/tracker/export/debtors?' + params.toString(), '_blank');
}
(function(){
    if (window.__trkExportMenuV14) return;
    window.__trkExportMenuV14 = true;
    document.addEventListener('click', function(e) {
        var t = e.target;
        if (!t || !t.closest) return;
        if (t.closest('#exportMenuBtn')) { toggleExportMenu(); return; }
        var item = t.closest('.export-menu-item');
        if (item) { runExportForm(item.getAttribute('data-form')); return; }
        var drop = document.getElementById('exportMenuDrop');
        if (drop && drop.style.display === 'block' && !t.closest('.export-menu-wrap')) {
            drop.style.display = 'none';
        }
    });
})();

# PATCH v1.0.14: кто не заполнил отчёт (один endpoint, без дубля calendar/export)
@app.route('/api/tracker/export/debtors')
@login_required
def api_export_debtors_v14():
    from datetime import date as _date
    from flask import send_file
    try:
        import openpyxl
        from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
    except ImportError:
        return jsonify({'success': False, 'error': 'openpyxl не установлен'}), 500
    d = (request.args.get('date') or '').strip() or _date.today().strftime('%Y-%m-%d')
    dept_id = (request.args.get('department') or '').strip()
    team_id = (request.args.get('team') or '').strip()
    data = db.load_all()
    employees = list(data.get('employees') or [])
    teams = data.get('teams') or []
    holidays = data.get('holidays') or {}
    all_logs = data.get('log') or []
    emp_team = {}
    for t in teams:
        tname = t.get('name') or ''
        mgr = (t.get('manager_id') or '').strip()
        if mgr:
            emp_team.setdefault(mgr, tname)
        for mid in (t.get('member_ids') or []):
            if mid:
                emp_team.setdefault(mid, tname)
        try:
            for r in db.query('SELECT employee_id FROM team_members WHERE team_id=?', (t.get('id'),)):
                eid = r.get('employee_id')
                if eid:
                    emp_team.setdefault(eid, tname)
        except Exception:
            pass
    if dept_id:
        employees = [e for e in employees if e.get('department_id') == dept_id]
    if team_id:
        member_ids = set()
        for t in teams:
            if t.get('id') != team_id:
                continue
            member_ids.update(t.get('member_ids') or [])
            if t.get('manager_id'):
                member_ids.add(t['manager_id'])
            try:
                for r in db.query('SELECT employee_id FROM team_members WHERE team_id=?', (team_id,)):
                    if r.get('employee_id'):
                        member_ids.add(r['employee_id'])
            except Exception:
                pass
        employees = [e for e in employees if e.get('id') in member_ids]
    is_workday = True
    try:
        wd = _date.fromisoformat(d).weekday()
        if wd >= 5 or d in holidays:
            is_workday = False
    except Exception:
        pass
    reported = {l.get('employee_id') for l in all_logs if l.get('date') == d}
    debtors = []
    for e in employees:
        if e.get('fired'):
            continue
        on_absence = False
        for v in (e.get('vacations') or []):
            f = v.get('from') or v.get('date_from') or ''
            tto = v.get('to') or v.get('date_to') or ''
            if f and tto and f <= d <= tto and (v.get('type') or 'vacation') != 'remote':
                on_absence = True
                break
        if on_absence:
            continue
        if e.get('id') not in reported:
            debtors.append(e)
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = 'Не заполнили отчёт'
    header_fill = PatternFill('solid', fgColor='C0392B')
    header_font = Font(bold=True, color='FFFFFF')
    thin = Side(style='thin', color='CCCCCC')
    border = Border(left=thin, right=thin, top=thin, bottom=thin)
    ws.merge_cells('A1:E1')
    note = '' if is_workday else ' (выходной/праздник — справочно)'
    ws['A1'] = f'Не заполнили отчёт за {d}{note}'
    ws['A1'].font = Font(bold=True, size=14)
    ws['A1'].alignment = Alignment(horizontal='center')
    for ci, h in enumerate(['№', 'ФИО', 'Отдел', 'Команда', 'Примечание'], start=1):
        c = ws.cell(row=3, column=ci, value=h)
        c.font = header_font
        c.fill = header_fill
        c.border = border
        c.alignment = Alignment(horizontal='center')
    row = 4
    for i, e in enumerate(debtors, start=1):
        ws.cell(row=row, column=1, value=i).border = border
        ws.cell(row=row, column=2, value=e.get('name', '')).border = border
        ws.cell(row=row, column=3, value=e.get('department') or e.get('department_id') or '').border = border
        ws.cell(row=row, column=4, value=emp_team.get(e.get('id'), '')).border = border
        ws.cell(row=row, column=5, value='' if is_workday else 'не рабочий день').border = border
        row += 1
    total_active = len([e for e in employees if not e.get('fired')])
    ws.cell(row=row + 1, column=2, value=f'Итого: {len(debtors)} из {total_active} не заполнили').font = Font(bold=True)
    for col, w in (('A', 6), ('B', 30), ('C', 20), ('D', 20), ('E', 18)):
        ws.column_dimensions[col].width = w
    from io import BytesIO
    output = BytesIO()
    wb.save(output)
    output.seek(0)
    return send_file(
        output,
        mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        as_attachment=True,
        download_name=f'debtors_{d}.xlsx',
    )
